        "Per cilvēku vai dzīvnieku run bieži nozīmē skriet vai iet ātrā solī.",
        "Per il film potrai programmare notizie e informarti.",
        "Kustībai kājām A1 līmenī visbiežāk salīdzina vai a correre."
