        "Vuoto lateo, sì digiti parvieto lateu un noliec to uz galda, gultas vai citas virsmas.",
        "Tassa non mentire, kas nozīmē, ka kaut kas jau atrodas vai guļ.",
        "A1 līmenī svarīgākā atšˈirība ir: vide = nolikt, mensonge = atrasties guļus."
