      "explanation": "Galvenā doma: fernsehen ir sadalāms darbības vārds — vedo la felce, la più felce che tu sia. Tas nozīmē skatīties televīziju. Ne jaukt ar Laatvārdu das Fernsehen (televīzija kā medijs).",
